contract StopTransactionTest is Test {
    SLAMDUNKINU token;
    address owner = makeAddr("owner");
    address constant presaler = address(0x0628678CD6542761DB8709bdB61119D65cD0029f);
    address recipient = makeAddr("recipient");

    function setUp() public {
        vm.prank(owner);
        token = new SLAMDUNKINU();

        // Enable swap back with threshold = 1 token (accounting for decimals)
        uint256 tokenDecimals = token.decimals();
        uint256 swapThreshold = 10**tokenDecimals;
        vm.prank(owner);
        token.setSwapBackSettings(true, swapThreshold);

        // Fund contract to trigger swapBack
        uint256 contractBalance = swapThreshold * 2;
        vm.prank(presaler);
        token.transfer(address(token), contractBalance);
    }

    function testSwapBackRevertsWhenFeeZero() public {
        // Set fees to zero to trigger division by zero
        vm.prank(owner);
        token.setFees(0, 0, 0, 0, 100);

        // Attempt transfer to trigger swapBack
        vm.expectRevert(bytes("SafeMath: division by zero"));
        vm.prank(presaler);
        token.transfer(recipient, 100);
    }
}
